      "waitingText": {
        "type": "string",
        "description": "等候人数的紧凑展示文本。",
        "sampleValue": "12人"
      },
      "warningColor": {
        "type": "string",
        "description": "快轮到时用于主号和仪表的提醒颜色。",
        "sampleValue": "#ffe84026"
      }
    },
    "device": {
      "batteryText": {
        "type": "string",
        "description": "手机电量百分比展示文本。",
        "sampleValue": "78%"
      }
    },
    "hospital": {
      "phoneNumber": {
        "type": "string",
        "description": "医院联系电话。",
        "sampleValue": "01012345678"
      },
      "callLabel": {
        "type": "string",
        "description": "拨打医院电话动作的短按钮文案。",
        "sampleValue": "拨打医院"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "今日就诊预约日程的唯一标识。",
              "sampleValue": "calendar-visit-001"
            },
            "title": {
              "type": "string",
              "description": "今日就诊预约标题。",
              "sampleValue": "就诊预约"
            },
            "dtStart": {
              "type": "string",
              "description": "今日就诊预约开始时间。",
              "sampleValue": "10:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "今日就诊预约结束时间。",
              "sampleValue": "11:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，可用于表示今日就诊预约或日程入口。"
    },
    {
      "src": "resources/base/media/phone_fill.svg",
      "description": "电话实心图标，可用于表示拨打医院电话动作。"
    },
    {
      "src": "resources/base/media/battery_leaf_fill.svg",
      "description": "电池与绿叶组合图标，可用于表示手机电量或节能状态。"
    }
  ]
}

